solutionFiles.Program.cs:
// Mission: make a player card for your game!
string player = "PixelFox";
int level = 3;

// 1. Make an int variable called coins, starting at 250.
int coins = 250;

// 2. The player found 50 more coins! Add 50 to coins.
coins = coins + 50;

// 3. Fix these lines so they print the values, not the names. Use $ and { }.
Console.WriteLine($"Player: {player}");
Console.WriteLine($"Level: {level}");
// Then add a line that prints the coins, like: Coins: 300
Console.WriteLine($"Coins: {coins}");

