Fix the Level line the same way, then add a line for `Coins: {coins}`.

lessons.exampleCode:
// A receipt: types, var, const and formatted interpolation.
const decimal TaxRate = 0.08m;   // the m makes it a decimal literal

string item = "Mechanical keyboard";
int quantity = 2;
decimal price = 49.99m;

var subtotal = price * quantity; // int * decimal → decimal, so var infers decimal
var tax = subtotal * TaxRate;

Console.WriteLine($"{quantity} x {item} @ {price:F2}");
Console.WriteLine($"Subtotal: {subtotal:F2}");
Console.WriteLine($"Tax:      {tax:F2}");
Console.WriteLine($"Total:    {subtotal + tax:F2}");
Console.WriteLine();

int pizzas = 7;
int people = 2;
Console.WriteLine($"{pizzas} / {people} = {pizzas / people}   (integer division)");
Console.WriteLine($"(double){pizzas} / {people} = {(double)pizzas / people}");
Console.WriteLine($"{pizzas} % {people} = {pizzas % people}   (the remainder)");

